-- Read-only metadata. Not a migration.
select jsonb_build_object(
'columns',(select jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'type',format_type(a.atttypid,a.atttypmod),'nullable',not a.attnotnull,'default',pg_get_expr(ad.adbin,ad.adrelid)) order by c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef ad on ad.adrelid=c.oid and ad.adnum=a.attnum where n.nspname='public' and c.relkind in ('r','p') and a.attnum>0 and not a.attisdropped and c.relname<>'spatial_ref_sys'),
'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_arguments(p.oid),'identity_arguments',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'language',l.lanname,'volatility',p.provolatile,'security_definer',p.prosecdef,'config',p.proconfig,'body',p.prosrc) order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname='public' and p.proname in ('set_master_location_and_timestamp','refresh_school_apartment_serving','cleanup_recurring_etl','is_etl_admin','filter_school_ids','set_academy_proximity_location','nearby_academy_addresses','nearby_academy_addresses_for_school','region_from_address','etl_staging_depth','public_table_sizes','public_data_freshness','nearby_care_centers','curriculum_ref_is_active','curriculum_like_counts','curriculum_item_ranking'))
) as definitions;
